WITH base AS (SELECT *, LENGTH(account_type) AS account_type_length, COALESCE(status, 'UNKNOWN') AS status_clean FROM accounts WHERE balance IS NOT NULL) SELECT dim.segment, a.status, COUNT(*) AS num_rows, MIN(a.account_type_length) AS min_account_type_length, GROUPING_ID() AS level_id FROM base a INNER JOIN customers dim ON a.customer_id = dim.id GROUP BY GROUPING SETS ((dim.segment, a.status), (dim.segment), ())
